// Simulate: user types '0' → chat-realtime.ts:185 → launchOptions → RealtimeTalkSession
const userInput = '0';
const vadThreshold = userInput.trim() ? Number(userInput) : undefined;

const launchOptions: RealtimeTalkLaunchOptions = { model: 'gpt-5.5', voice: 'alloy', vadThreshold };
console.log('launchOptions:', JSON.stringify(launchOptions));

function compactLaunchParams(params: Record<string, unknown>) {
  return Object.fromEntries(Object.entries(params).filter(([, v]) => v !== undefined));
}
// What gets sent to Gateway via RPC 'talk.client.create'
const compact = compactLaunchParams({ sessionKey: 'agent:main:main', ...launchOptions });
console.log('Sent to Gateway:', JSON.stringify(compact));
"
launchOptions: {"model":"gpt-5.5","voice":"alloy","vadThreshold":0}
Sent to Gateway: {"sessionKey":"agent:main:main","model":"gpt-5.5","voice":"alloy","vadThreshold":0}

=== vadThreshold=0 PRESERVED through the entire pipeline ✅ ===

Contrast with current main:
  Number("0") || undefined = undefined
  → compactLaunchParams strips undefined
  → vadThreshold=0 silently lost ❌
```

The real `RealtimeTalkSession` and `compactLaunchParams` are exercised end-to-end. The value `0` survives from user input all the way through to the Gateway RPC payload.

